// ── Process vs Thread in .NET ──

// Creating a new PROCESS
using System.Diagnostics;
var process = Process.Start("notepad.exe");
// notepad runs in a completely separate memory space
// if it crashes, our app is unaffected

// ── Threads sharing memory (race condition demo) ──
int counter = 0;  // shared state

var t1 = new Thread(() => {
    for (int i = 0; i < 100000; i++) counter++;  // NOT thread-safe!
});
var t2 = new Thread(() => {
    for (int i = 0; i < 100000; i++) counter++;  // NOT thread-safe!
});

t1.Start(); t2.Start();
t1.Join();  t2.Join();
Console.WriteLine(counter);  // Expected: 200000, Actual: ~150000-190000 (race condition!)

// ── Fix with lock ──
int safeCounter = 0;
object lockObj = new object();

var t3 = new Thread(() => {
    for (int i = 0; i < 100000; i++)
        lock (lockObj) { safeCounter++; }  // thread-safe
});
var t4 = new Thread(() => {
    for (int i = 0; i < 100000; i++)
        lock (lockObj) { safeCounter++; }  // thread-safe
});

t3.Start(); t4.Start();
t3.Join();  t4.Join();
Console.WriteLine(safeCounter);  // Always: 200000 ✓

// ── Modern approach: use Task (ThreadPool) ──
await Task.WhenAll(
    Task.Run(() => Console.WriteLine($"Task on thread {Environment.CurrentManagedThreadId}")),
    Task.Run(() => Console.WriteLine($"Task on thread {Environment.CurrentManagedThreadId}"))
);

// ── Deadlock in C# (threading) ──
object lockA = new object();
object lockB = new object();

// Thread 1:
Task.Run(() => {
    lock (lockA) {          // acquires lockA
        Thread.Sleep(100);
        lock (lockB) { }    // waits for lockB → BLOCKED!
    }
});

// Thread 2:
Task.Run(() => {
    lock (lockB) {          // acquires lockB
        Thread.Sleep(100);
        lock (lockA) { }    // waits for lockA → BLOCKED!
    }
});
// DEADLOCK! Both threads wait forever.

// ── FIX: Consistent lock ordering ──
// Thread 1:
lock (lockA) { lock (lockB) { /* work */ } }

// Thread 2:
lock (lockA) { lock (lockB) { /* work */ } }  // SAME order!
// No deadlock possible!

// ── Virtual Memory Visualization ──
//
// Process A (virtual)    Page Table A    Physical RAM
// ┌────────────┐        ┌──────────┐    ┌────────────┐
// │ Page 0     │ ──────→│ Frame 3  │───→│ Frame 0    │
// │ Page 1     │ ──────→│ Frame 7  │    │ Frame 1    │
// │ Page 2     │ ──────→│ DISK     │    │ Frame 2    │
// │ Page 3     │ ──────→│ Frame 1  │    │ Frame 3 ←A │
// └────────────┘        └──────────┘    │ Frame 4    │
//                                       │ Frame 5 ←B │
// Process B (virtual)    Page Table B    │ Frame 6    │
// ┌────────────┐        ┌──────────┐    │ Frame 7 ←A │
// │ Page 0     │ ──────→│ Frame 5  │    └────────────┘
// │ Page 1     │ ──────→│ Frame 4  │
// └────────────┘        └──────────┘
//
// Process A's Page 2 is on DISK → accessing it triggers a PAGE FAULT
// OS loads it from swap into a free frame (or evicts another page)

// ── In C#, you don't manage pages directly, but you see effects:
// OutOfMemoryException → virtual address space exhausted
// High page fault rate → app is slow, needs more RAM
// GC pressure → .NET manages within virtual memory

// ── Process vs Thread in C# ──

// Creating a new PROCESS (expensive, isolated)
var process = Process.Start("notepad.exe");
// Completely separate memory space
// Can't access this process's variables

// Creating THREADS within this process
// Method 1: Manual thread
var thread = new Thread(() => Console.WriteLine("Hello from thread!"));
thread.Start();

// Method 2: Thread Pool (preferred)
ThreadPool.QueueUserWorkItem(_ => Console.WriteLine("Thread pool!"));

// Method 3: Task (best for modern C#)
var task = Task.Run(() => {
    // Runs on a thread pool thread
    return ComputeResult();
});

// Method 4: async/await (doesn't block threads)
async Task<string> FetchDataAsync() {
    // Thread is RELEASED during the await
    var response = await httpClient.GetStringAsync("https://api.com/data");
    // Thread pool thread resumes here
    return response;
}

// Method 5: Parallel (CPU-bound work)
Parallel.ForEach(items, item => {
    ProcessItem(item); // runs on multiple cores
});
